// Standardize job data and validate user authentication
const standardizedJobs = [];

// Get authenticated user ID from environment
const userId = process.env.USER_ID;
if (!userId) {
  throw new Error('USER_ID environment variable is required');
}

console.log('Processing jobs for user:', userId);

for (const item of $input.all()) {
  try {
    // Extract job data with flexible parsing
    const rawTitle = item.json.title || 'Unknown Position';
    let company = 'Unknown Company';
    let jobTitle = rawTitle;

    // Common patterns: "Title at Company" or "Company - Title"
    const atMatch = rawTitle.match(/(.+?)\s+at\s+(.+)$/i);
    const dashMatch = rawTitle.match(/(.+?)\s+-\s+(.+)$/i);

    if (atMatch) {
      jobTitle = atMatch[1].trim();
      company = atMatch[2].trim();
    } else if (dashMatch) {
      company = dashMatch[1].trim();
      jobTitle = dashMatch[2].trim();
    }

    // Create standardized job object
    const standardJob = {
      user_id: userId,
      title: jobTitle,
      company: company,
      location: 'Remote',
      url: item.json.link || item.json.guid || '',
      description: item.json.contentSnippet || item.json.description || item.json.content || '',
      source: 'RSS Job Board',
      published: item.json.pubDate || item.json.isoDate || new Date().toISOString(),
      rawData: {
        originalTitle: item.json.title,
        guid: item.json.guid,
        categories: item.json.categories || [],
        creator: item.json.creator
      }
    };

    // Basic quality validation
    if (standardJob.url && standardJob.title && standardJob.title !== 'Unknown Position') {
      standardizedJobs.push({ json: standardJob });
      console.log('✅ Added:', standardJob.title, 'at', standardJob.company);
    } else {
      console.log('⚠️ Skipped low-quality job:', standardJob.title);
    }

  } catch (error) {
    console.error('❌ Error processing job:', error.message);
  }
}

console.log(`📊 Processed ${$input.all().length} raw items → ${standardizedJobs.length} valid jobs`);

if (standardizedJobs.length === 0) {
  throw new Error('No valid jobs found. Check RSS feed data.');
}

return standardizedJobs;

// Parse AI response and prepare final job data
const aiResponse = $input.first().json;
const jobData = $('Standardize Job Data').item.json;
const stagingResponse = $('Save to Staging').item.json;

// Get staging ID
let stagingId = null;
if (Array.isArray(stagingResponse) && stagingResponse.length > 0) {
  stagingId = stagingResponse[0].id;
} else if (stagingResponse.id) {
  stagingId = stagingResponse.id;
}

if (!stagingId) {
  throw new Error('Failed to get staging ID');
}

// Parse AI scoring result
let aiResult = { score: 5, reasoning: 'AI parsing failed' };
try {
  if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
    const aiText = aiResponse.choices[0].message.content.trim();
    const cleanedText = aiText.replace(/```json\n?|```/g, '').trim();
    aiResult = JSON.parse(cleanedText);
  }
} catch (error) {
  console.error('AI response parsing error:', error.message);
}

// Create final job object
const finalJob = {
  company: jobData.company,
  role: jobData.title,
  location: jobData.location,
  url: jobData.url,
  description: jobData.description,
  source: jobData.source,
  ai_match_score: Math.min(Math.max(aiResult.score || 5, 1), 10),
  status: 'To Review',
  user_id: jobData.user_id,
  ai_reasoning: (aiResult.reasoning || 'No reasoning provided').substring(0, 500),
  stagingId: stagingId
};

console.log('🎯 Job scored:', finalJob.ai_match_score, '-', finalJob.role, 'at', finalJob.company);

return { json: finalJob };
